create schema if not exists private;
create or replace function private.is_editor()
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())); $$;
revoke all on function private.is_editor() from public;
grant usage on schema private to authenticated;
grant execute on function private.is_editor() to authenticated;
drop policy if exists "admins manage admin roster" on public.admin_users;
drop policy if exists "public read active categories" on public.categories;
drop policy if exists "admins manage categories" on public.categories;
drop policy if exists "public read active retailers for published offers" on public.retailers;
drop policy if exists "admins manage retailers" on public.retailers;
drop policy if exists "public read published products" on public.products;
drop policy if exists "admins manage products" on public.products;
drop policy if exists "public read active offers for published products" on public.product_offers;
drop policy if exists "admins manage offers" on public.product_offers;
drop policy if exists "public read published articles" on public.articles;
drop policy if exists "admins manage articles" on public.articles;
drop policy if exists "public read published article product links" on public.article_products;
drop policy if exists "admins manage article product links" on public.article_products;
drop policy if exists "admins manage editorial sources" on public.editorial_sources;
drop policy if exists "admins manage product sources" on public.product_sources;
drop policy if exists "admins read click events" on public.affiliate_click_events;
drop function if exists public.is_editor();
create policy "admins manage admin roster" on public.admin_users for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read active categories" on public.categories for select to anon, authenticated using (is_active or private.is_editor());
create policy "admins manage categories" on public.categories for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read active retailers for published offers" on public.retailers for select to anon, authenticated using ((is_active and exists (select 1 from public.product_offers o join public.products p on p.id=o.product_id where o.retailer_id=retailers.id and o.status='active' and p.status='published')) or private.is_editor());
create policy "admins manage retailers" on public.retailers for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read published products" on public.products for select to anon, authenticated using (status='published' or private.is_editor());
create policy "admins manage products" on public.products for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read active offers for published products" on public.product_offers for select to anon, authenticated using ((status='active' and exists (select 1 from public.products p where p.id=product_offers.product_id and p.status='published')) or private.is_editor());
create policy "admins manage offers" on public.product_offers for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read published articles" on public.articles for select to anon, authenticated using (status='published' or private.is_editor());
create policy "admins manage articles" on public.articles for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "public read published article product links" on public.article_products for select to anon, authenticated using (exists (select 1 from public.articles a where a.id=article_products.article_id and a.status='published') or private.is_editor());
create policy "admins manage article product links" on public.article_products for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "admins manage editorial sources" on public.editorial_sources for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "admins manage product sources" on public.product_sources for all to authenticated using (private.is_editor()) with check (private.is_editor());
create policy "admins read click events" on public.affiliate_click_events for select to authenticated using (private.is_editor());
create index if not exists products_category_id_idx on public.products(category_id);
create index if not exists articles_category_id_idx on public.articles(category_id);
create index if not exists product_offers_retailer_id_idx on public.product_offers(retailer_id);
create index if not exists article_products_product_id_idx on public.article_products(product_id);
create index if not exists product_sources_source_id_idx on public.product_sources(source_id);
create index if not exists affiliate_click_events_offer_id_idx on public.affiliate_click_events(offer_id);
create index if not exists affiliate_click_events_product_id_idx on public.affiliate_click_events(product_id);
create index if not exists affiliate_click_events_article_id_idx on public.affiliate_click_events(article_id);
